// Batch driver: puts MANY fenced blocks into ONE --e argument separated by marker paragraphs,
// then splits the output back apart. One executable invocation for N cases.
import { phase } from '/tmp/probe/p.mjs';

export function multi(snippets) {
  // snippets: array of strings (each is raw markdown, usually a fenced block)
  const parts = [];
  for (let i = 0; i < snippets.length; i++) {
    parts.push('ZQMARK' + i + 'ZQ');
    parts.push(snippets[i]);
  }
  parts.push('ZQMARK' + snippets.length + 'ZQ');
  const doc = parts.join('\n\n');
  const out = phase('e', doc);
  const res = [];
  for (let i = 0; i < snippets.length; i++) {
    const a = out.indexOf('<p>ZQMARK' + i + 'ZQ</p>');
    const b = out.indexOf('<p>ZQMARK' + (i + 1) + 'ZQ</p>');
    if (a < 0 || b < 0) { res.push('!!!SPLITFAIL!!! ' + JSON.stringify(out)); continue; }
    res.push(out.slice(a + ('<p>ZQMARK' + i + 'ZQ</p>').length, b).replace(/^\n+/, '').replace(/\n+$/, ''));
  }
  return res;
}

export function fence(lang, code) {
  return '```' + lang + '\n' + code + '\n```';
}

// CLI: node multi.mjs '<json array of snippet strings>'
if (process.argv[2]) {
  const snips = JSON.parse(process.argv[2]);
  const outs = multi(snips);
  for (let i = 0; i < snips.length; i++) {
    console.log('### IN=' + JSON.stringify(snips[i]));
    console.log('OUT=' + JSON.stringify(outs[i]));
  }
}

