class R {
  constructor(b, p = 0) { this.b = b; this.p = p; this.refs = []; }
  u8() { return this.b[this.p++]; }
  i32() { const v = this.b.readInt32LE(this.p); this.p += 4; return v; }
  u32() { const v = this.b.readUInt32LE(this.p); this.p += 4; return v; }
  bytes(n) { const v = this.b.slice(this.p, this.p + n); this.p += n; return v; }
  r() {
    const c = this.u8();
    const flag = c & 0x80;
    const t = String.fromCharCode(c & 0x7f);
    let idx = -1;
    const alloc = (v) => { if (flag) { if (idx < 0) { idx = this.refs.length; this.refs.push(v); } else this.refs[idx] = v; } return v; };
    switch (t) {
      case '0': return null;
      case 'N': return alloc(null);
      case 'F': return alloc(false);
      case 'T': return alloc(true);
      case '.': return alloc('...');
      case 'S': return alloc('StopIteration');
      case 'i': return alloc(this.i32());
      case 'g': { const v = this.b.readDoubleLE(this.p); this.p += 8; return alloc(v); }
      case 'f': { const n = this.u8(); return alloc(parseFloat(this.bytes(n).toString('latin1'))); }
