import { loadModule } from './mar.mjs';

export const OP = {
  CACHE:0, POP_TOP:1, PUSH_NULL:2, NOP:9,
  UNARY_NEGATIVE:11, UNARY_NOT:12, UNARY_INVERT:15,
  BINARY_SUBSCR:25, GET_ITER:68, LOAD_BUILD_CLASS:71, RETURN_VALUE:83,
  SETUP_ANNOTATIONS:85, LOAD_LOCALS:87,
  STORE_NAME:90, DELETE_NAME:91, UNPACK_SEQUENCE:92, FOR_ITER:93,
  STORE_ATTR:95, STORE_GLOBAL:97, SWAP:99,
  LOAD_CONST:100, LOAD_NAME:101, BUILD_TUPLE:102, BUILD_LIST:103, BUILD_SET:104,
  BUILD_MAP:105, LOAD_ATTR:106, COMPARE_OP:107, IMPORT_NAME:108, IMPORT_FROM:109,
  JUMP_FORWARD:110, POP_JUMP_IF_FALSE:114, POP_JUMP_IF_TRUE:115, LOAD_GLOBAL:116,
  IS_OP:117, CONTAINS_OP:118, COPY:120, RETURN_CONST:121, BINARY_OP:122,
  LOAD_FAST:124, STORE_FAST:125, RAISE_VARARGS:130, MAKE_FUNCTION:132,
  BUILD_SLICE:133, LOAD_DEREF:137, STORE_DEREF:138, JUMP_BACKWARD:140,
  EXTENDED_ARG:144, LIST_APPEND:145, SET_ADD:146, MAP_ADD:147,
  COPY_FREE_VARS:149, RESUME:151, FORMAT_VALUE:155, BUILD_CONST_KEY_MAP:156,
  BUILD_STRING:157, LIST_EXTEND:162, SET_UPDATE:163, DICT_MERGE:164, DICT_UPDATE:165,
  CALL:171, KW_NAMES:172, CALL_INTRINSIC_1:173, MAKE_CELL:135, LOAD_CLOSURE:136,
  YIELD_VALUE:150, RETURN_GENERATOR:75, POP_JUMP_IF_NONE:129, POP_JUMP_IF_NOT_NONE:128,
  BINARY_OP_ADD:0,
};
const NAMEOF = {}; for (const [k,v] of Object.entries(OP)) if (!(v in NAMEOF)) NAMEOF[v]=k;

const NB = ['+','&','//','<<','@','*','%','|','**','>>','-','/','^','+=','&=','//=','<<=','@=','*=','%=','|=','**=','>>=','-=','/=','^='];

// symbolic value wrappers
const N = (n) => ({ kind:'name', n });
const A = (o,a) => ({ kind:'attr', o, a });
const C = (f,args,kw) => ({ kind:'call', f, args, kw });
const T = (items) => ({ kind:'tuple', items });
const L = (items) => ({ kind:'list', items });
const D = (pairs) => ({ kind:'dict', pairs });
const B = (op,l,r) => ({ kind:'bin', op, l, r });

export function interp(co) {
  const b = co.code.__bytes;
  const st = [];
  const store = {};
  let ext = 0;
  const consts = co.consts, names = co.names;
  let kwnames = null;
  for (let i = 0; i + 1 < b.length; i += 2) {
    const op = b[i]; let arg = b[i+1] | ext; ext = 0;
    try {
    switch (op) {
      case OP.EXTENDED_ARG: ext = arg << 8; break;
      case OP.CACHE: case OP.RESUME: case OP.NOP: case OP.PUSH_NULL: case OP.SETUP_ANNOTATIONS:
      case OP.MAKE_CELL: case OP.COPY_FREE_VARS: case OP.RETURN_GENERATOR: break;
      case OP.LOAD_CONST: st.push({kind:'const', v: consts[arg]}); break;
      case OP.RETURN_CONST: break;
      case OP.LOAD_NAME: st.push(N(names[arg])); break;
      case OP.LOAD_GLOBAL: st.push(N(names[arg >> 1])); break;
      case OP.LOAD_FAST: case OP.LOAD_DEREF: case OP.LOAD_CLOSURE: st.push(N('<local>')); break;
      case OP.LOAD_ATTR: { const o = st.pop(); st.push(A(o, names[arg >> 1])); break; }
      case OP.STORE_NAME: { store[names[arg]] = st.pop(); break; }
      case OP.STORE_FAST: case OP.STORE_DEREF: st.pop(); break;
      case OP.BUILD_TUPLE: { const it = st.splice(st.length - arg, arg); st.push(T(it)); break; }
      case OP.BUILD_LIST: { const it = st.splice(st.length - arg, arg); st.push(L(it)); break; }
      case OP.BUILD_SET: { const it = st.splice(st.length - arg, arg); st.push({kind:'set', items:it}); break; }
      case OP.BUILD_MAP: { const it = st.splice(st.length - 2*arg, 2*arg); const p=[]; for(let k=0;k<it.length;k+=2)p.push([it[k],it[k+1]]); st.push(D(p)); break; }
      case OP.BUILD_CONST_KEY_MAP: { const keys = st.pop(); const vals = st.splice(st.length - arg, arg); const kk = keys.kind==='const'? keys.v : []; const p=[]; for(let k=0;k<arg;k++)p.push([{kind:'const',v:kk[k]}, vals[k]]); st.push(D(p)); break; }
      case OP.LIST_EXTEND: { const v = st.pop(); const l = st[st.length-1]; if (l && l.kind==='list') { if (v.kind==='const' && Array.isArray(v.v)) for (const x of v.v) l.items.push({kind:'const',v:x}); else l.items.push({kind:'spread', v}); } break; }
      case OP.SET_UPDATE: { const v = st.pop(); const l = st[st.length-1]; if (l&&l.kind==='set'){ if (v.kind==='const'&&Array.isArray(v.v)) for(const x of v.v) l.items.push({kind:'const',v:x}); } break; }
      case OP.LIST_APPEND: { const v = st.pop(); break; }
      case OP.KW_NAMES: kwnames = consts[arg]; break;
      case OP.CALL: { const args = st.splice(st.length - arg, arg); const f = st.pop(); const maybeNull = st[st.length-1]; if (maybeNull===undefined){} else if (maybeNull && maybeNull.kind==='nullmark') st.pop();
        let kw = null;
        if (kwnames) { const nk = kwnames.length; kw = {}; const kwv = args.splice(args.length-nk, nk); kwnames.forEach((k,ix)=>kw[k]=kwv[ix]); kwnames = null; }
        st.push(C(f, args, kw)); break; }
      case OP.BINARY_OP: { const r = st.pop(), l = st.pop(); st.push(B(NB[arg]||('op'+arg), l, r)); break; }
      case OP.BINARY_SUBSCR: { const k = st.pop(), o = st.pop(); st.push({kind:'sub', o, k}); break; }
      case OP.COPY: { st.push(st[st.length - arg]); break; }
      case OP.SWAP: { const n = st.length; const t = st[n-1]; st[n-1]=st[n-arg]; st[n-arg]=t; break; }
      case OP.POP_TOP: st.pop(); break;
      case OP.MAKE_FUNCTION: { const c = st.pop(); st.push({kind:'func', c: c.kind==='const'?c.v:null}); break; }
      case OP.FORMAT_VALUE: { const v = st.pop(); st.push({kind:'fmt', v}); break; }
      case OP.BUILD_STRING: { const it = st.splice(st.length-arg, arg); st.push({kind:'jstr', items: it}); break; }
      case OP.IMPORT_NAME: { st.pop(); st.pop(); st.push(N('<module '+names[arg]+'>')); break; }
      case OP.IMPORT_FROM: st.push(N(names[arg])); break;
      case OP.UNARY_NEGATIVE: { const v=st.pop(); st.push({kind:'neg', v}); break; }
      case OP.UNARY_INVERT: { const v=st.pop(); st.push({kind:'inv', v}); break; }
      default: /* unknown: best-effort ignore */ break;
    }
    } catch (e) { /* keep going */ }
  }
  return store;
}

export function show(v, depth = 0) {
  if (v === undefined) return 'undefined';
  if (v === null) return 'null';
  switch (v.kind) {
    case 'const': return JSON.stringify(v.v && v.v.__bytes ? '<bytes>' : v.v);
    case 'name': return v.n;
    case 'attr': return show(v.o) + '.' + v.a;
    case 'call': return show(v.f) + '(' + v.args.map(a=>show(a)).join(', ') + (v.kw? ', **'+JSON.stringify(Object.keys(v.kw)):'') + ')';
    case 'tuple': return '(' + v.items.map(a=>show(a)).join(', ') + ')';
    case 'list': return '[' + v.items.map(a=>show(a)).join(', ') + ']';
    case 'set': return '{' + v.items.map(a=>show(a)).join(', ') + '}';
    case 'dict': return '{' + v.pairs.map(([k,x])=>show(k)+': '+show(x)).join(', ') + '}';
    case 'bin': return '(' + show(v.l) + ' ' + v.op + ' ' + show(v.r) + ')';
    case 'sub': return show(v.o)+'['+show(v.k)+']';
    case 'func': return '<function>';
    case 'fmt': return 'f{'+show(v.v)+'}';
    case 'jstr': return 'JOIN(' + v.items.map(a=>show(a)).join(' + ') + ')';
    case 'spread': return '*'+show(v.v);
    case 'neg': return '-'+show(v.v);
    case 'inv': return '~'+show(v.v);
    default: return '?'+JSON.stringify(v).slice(0,80);
  }
}

export function findClass(mod, cls) {
  const stack = [mod];
  while (stack.length) {
    const co = stack.pop();
    for (const c of co.consts || []) if (c && c.__code) {
      if (c.name === cls) return c;
      stack.push(c);
    }
  }
  return null;
}

export function dumpLexer(modname, cls) {
  const mod = loadModule(modname);
  const co = findClass(mod, cls);
  if (!co) return 'CLASS NOT FOUND ' + cls;
  const store = interp(co);
  const out = [];
  for (const [k, v] of Object.entries(store)) {
    if (k === 'tokens') continue;
    out.push(k + ' = ' + show(v));
  }
  const tk = store['tokens'];
  out.push('tokens = {');
  if (tk && tk.kind === 'dict') {
    for (const [k, v] of tk.pairs) {
      out.push('  ' + show(k) + ': [');
      if (v && v.kind === 'list') for (const r of v.items) out.push('    ' + show(r) + ',');
      else out.push('    ' + show(v));
      out.push('  ],');
    }
  } else out.push('  ' + show(tk));
  out.push('}');
  return out.join('\n');
}

